// ===== CONFIGURACIÓN (editar aquí) =====
// Modo prueba, email de pruebas y canal se cambian en /admin-configuracion (tabla platform_settings).
// Si no se pueden leer los ajustes, se queda en modo prueba por seguridad.
const ajustes = {};
try { for (const r of $('Leer Ajustes de la Plataforma').all().map((i) => i.json)) if (r && r.key) ajustes[r.key] = r.value; } catch (e) {}
const MODO_PRUEBA = ajustes.modo_prueba !== false; // true = NADA sale a la empresa real; todo va a EMAIL_PRUEBA
const EMAIL_PRUEBA = typeof ajustes.email_prueba === 'string' && ajustes.email_prueba ? ajustes.email_prueba : 'idrabde0@gmail.com';
const CANAL = String(ajustes.canal_envio || 'gmail');                 // gmail | email_certificado | burofax
const PROVEEDOR_URL = String(ajustes.proveedor_certificado_url || '');
const REMITENTE = 'idrabde7@gmail.com';      // cuenta Gmail conectada en n8n (solo para el registro)
const ESTADOS_PERMITIDOS = ['under_review', 'reviewed', 'preparing_claim'];
// =======================================

const hook = $('Webhook POST /ptd-enviar').first().json;
const body = hook.body || {};
const caso = $('Obtener Caso de Supabase').first().json || {};
const partes = $('Leer Contraparte').all().map((i) => i.json).filter((j) => j && !j.error && Object.keys(j).length);

const fallo = (httpCode, error) => [{ json: { ok: false, httpCode, error } }];

if (!caso.id) return fallo(404, 'Caso no encontrado');
if (!ESTADOS_PERMITIDOS.includes(caso.status)) {
  return fallo(409, 'El caso no se puede enviar en su estado actual (' + caso.status + ')');
}

const asunto = String(body.editedSubject || caso.claim_draft_subject || '').trim();
const cuerpo = String(body.editedBody || caso.claim_draft_body || '').trim();
const plano = cuerpo.replace(/\*\*/g, '');
if (!asunto || plano.length < 200) return fallo(422, 'El caso no tiene un borrador valido para enviar');
if (/\[[^\]]*\]|XXX|YYYY/.test(plano)) return fallo(422, 'El borrador contiene marcadores sin completar');

// Destinatario real (solo se usa fuera del modo prueba)
const emailOf = (r) => r.email || r.contact_email || r.company_email || r.email_address ||
  (r.contact_details && (r.contact_details.email || r.contact_details.contact_email)) || '';
const parte = partes.find((p) => emailOf(p));
// Si el caso no trae el email de la empresa, se usa el de PTD-08 (directorio o búsqueda con IA verificada)
let buscado = {};
try { buscado = $('Buscar Destinatario (PTD-08)').first().json || {}; } catch (e) { buscado = {}; }
const emailBuscado = buscado.found && buscado.channel === 'email' ? String(buscado.email || '') : '';
const candidato = parte ? emailOf(parte) : (String(body.recipientEmail || '').trim() || emailBuscado);
const destinatarioReal = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(candidato) ? candidato : '';
if (!MODO_PRUEBA && !destinatarioReal) {
  const motivo = buscado.found && buscado.channel && buscado.channel !== 'email'
    ? 'la empresa solo admite reclamaciones por ' + buscado.channel + (buscado.formUrl ? ' (' + buscado.formUrl + ')' : '')
    : (buscado.reason || 'no se encontró un canal oficial');
  return fallo(422, 'No hay email de la empresa reclamada para este caso: ' + motivo);
}
const destino = MODO_PRUEBA ? EMAIL_PRUEBA : destinatarioReal;

// Canal certificado elegido en el panel pero sin proveedor configurado: no se envía por otro canal sin avisar
if (CANAL !== 'gmail' && !PROVEEDOR_URL) {
  return fallo(501, 'Canal "' + CANAL + '" seleccionado en el panel, pero falta configurar el proveedor (proveedor_certificado_url y su credencial en n8n)');
}

// Asunto: siempre lleva la referencia para poder asociar las respuestas
const reference = caso.reference || body.reference || '';
let subjectBase = asunto;
if (reference && !subjectBase.includes(reference)) subjectBase += ' - Ref. ' + reference;
const subject = (MODO_PRUEBA ? '[PRUEBA] ' : '') + subjectBase;

// Cuerpo HTML (negrita **x** -> <strong>)
const esc = (s) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const parrafos = esc(cuerpo)
  .split(/\n{2,}/)
  .map((par) => '<p style="margin:0 0 14px 0;">' + par.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>').replace(/\n/g, '<br>') + '</p>')
  .join('');
const banner = MODO_PRUEBA
  ? '<div style="background:#fef3c7;border:1px solid #f59e0b;padding:10px;margin-bottom:16px;font-size:13px;color:#78350f;"><strong>CORREO DE PRUEBA.</strong> No se ha enviado a la empresa reclamada' + (destinatarioReal ? ' (' + esc(destinatarioReal) + ')' : '') + '.</div>'
  : '';
const html = '<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#111;">' + banner + parrafos + '</div>';

// Plazo: el que promete el propio escrito (por ejemplo "DIEZ (10) DIAS NATURALES")
let dias = 14;
const m = plano.match(/\((\d{1,3})\)\s*D[ÍI]AS\s+NATURALES/i) || plano.match(/(\d{1,3})\s*d[ií]as\s+naturales/i);
if (m) dias = Number(m[1]);
const ahora = new Date();
const vence = new Date(ahora.getTime() + dias * 24 * 3600 * 1000);
const venceTexto = vence.toLocaleDateString('es-ES', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/Madrid' });

// Adjuntos: la web envia URLs firmadas temporales en body.documents
const docs = Array.isArray(body.documents) ? body.documents : [];
const binary = {};
const adjuntos = [];
const noAdjuntados = [];
let idx = 1;
for (const d of docs.slice(0, 10)) {
  const nombre = d.name || ('documento_' + idx);
  try {
    if (!/^https:\/\/[a-z0-9]+\.supabase\.co\/storage\//.test(d.url || '')) throw new Error('url no permitida');
    const buf = await this.helpers.httpRequest({ method: 'GET', url: d.url, encoding: 'arraybuffer' });
    const data = Buffer.isBuffer(buf) ? buf : Buffer.from(buf);
    binary['data' + idx] = await this.helpers.prepareBinaryData(data, nombre, d.type || 'application/octet-stream');
    adjuntos.push(nombre);
    idx++;
  } catch (e) {
    noAdjuntados.push(nombre);
  }
}
if (noAdjuntados.length) return fallo(422, 'No se pudieron descargar los adjuntos: ' + noAdjuntados.join(', '));

const resumen = (MODO_PRUEBA ? '[PRUEBA] ' : '') + plano.slice(0, 280).replace(/\s+/g, ' ') + '...' +
  (adjuntos.length ? ' Adjuntos: ' + adjuntos.join(', ') : '');

const out = {
  json: {
    ok: true,
    modoPrueba: MODO_PRUEBA,
    caseId: caso.id,
    ownerId: caso.owner_id,
    reference,
    destino,
    destinatarioReal,
    remitente: REMITENTE,
    subject,
    html,
    resumen,
    dias,
    venceTexto,
    sentAt: ahora.toISOString(),
    dueAt: vence.toISOString(),
    adjuntos,
    canal: CANAL,
    proveedorUrl: PROVEEDOR_URL
  }
};
if (Object.keys(binary).length) out.binary = binary;
return [out];

const caso = $('Obtener Caso de Supabase').first().json || {};
const partes = $('Leer Contraparte').all().map(i => i.json).filter(j => j && j.name);
return [{ json: {
  companyName: (partes[0] && partes[0].name) || caso.title || '',
  category: '',
  caseId: caso.id || null
} }];

